import { SYSTEM_DISPLAY_DETAIL } from "../constants/systemConstants";
import getSystemDisplayMode from "./getSystemDisplayMode";

// A source annotation of a system instance (stamped by applySystemService).
export function isSystemSourceAnnotation(annotation) {
  return Boolean(annotation?.systemApplied);
}

// An annotation generated by a system instance.
export function isSystemGeneratedAnnotation(annotation) {
  return Boolean(annotation?.systemSourceAnnotationId);
}

/**
 * Display filter of the system instances for one editor ("in2d" | "in3d"),
 * applied where the editors filter what they draw (never in
 * useAnnotationsV2: quantities and listings keep every annotation).
 *
 *   - instance in SOURCE mode: its generated annotations are dropped;
 *   - instance in DETAIL mode: the generated annotations are kept and the
 *     source is hidden — flagged `systemSourceHidden` (2D: still in the list,
 *     so a click on the detail resolves to it and the edit layer draws it once
 *     selected) or dropped (`dropHiddenSources`, 3D);
 *   - a generated annotation whose source is not in the list is dropped.
 *
 * Returns the input array itself when it holds no system annotation.
 */
export default function applySystemDisplay(
  annotations,
  editorKey,
  { dropHiddenSources = false } = {}
) {
  if (!annotations?.length) return annotations;

  let modeBySourceId = null;
  let hasGenerated = false;
  for (const a of annotations) {
    if (isSystemSourceAnnotation(a)) {
      if (!modeBySourceId) modeBySourceId = new Map();
      modeBySourceId.set(a.id, getSystemDisplayMode(a, editorKey));
    } else if (isSystemGeneratedAnnotation(a)) {
      hasGenerated = true;
    }
  }
  if (!modeBySourceId && !hasGenerated) return annotations;

  const result = [];
  for (const a of annotations) {
    if (isSystemGeneratedAnnotation(a)) {
      const mode = modeBySourceId?.get(a.systemSourceAnnotationId);
      if (mode === SYSTEM_DISPLAY_DETAIL) result.push(a);
      continue;
    }
    if (modeBySourceId?.get(a.id) === SYSTEM_DISPLAY_DETAIL) {
      if (!dropHiddenSources) result.push({ ...a, systemSourceHidden: true });
      continue;
    }
    result.push(a);
  }
  return result;
}

// Selection ids of a lasso / select-all over a list that mixes instances and
// regular annotations: a generated annotation stands for its source (the
// instance is selected as a whole), duplicates removed.
export function resolveSystemSelectionIds(annotationIds, annotations) {
  if (!annotationIds?.length) return annotationIds;
  const sourceIdById = new Map();
  for (const a of annotations ?? []) {
    if (isSystemGeneratedAnnotation(a))
      sourceIdById.set(a.id, a.systemSourceAnnotationId);
  }
  if (sourceIdById.size === 0) return annotationIds;
  return [...new Set(annotationIds.map((id) => sourceIdById.get(id) ?? id))];
}
